package dk.starswordmaster.progression;
import dk.starswordmaster.PlayerStore;
import org.junit.*;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;
public class PointSeparationTest {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 private PlayerProgress atXp(int xp){var p=new Properties();p.setProperty("xp",Integer.toString(xp));return PlayerProgress.fromProperties(p);}
 @Test public void newCharacterHasNoFreePoints(){var p=new PlayerProgress();assertEquals(0,p.statPoints().intValueExact());assertEquals(0,p.points().intValueExact());assertFalse(p.spendStat(PlayerProgress.Stat.STRENGTH));assertFalse(p.unlock("spark"));}
 @Test public void historicalLevelsRetainExactlyFiveStatPoints(){int xp=0;for(int level=1;level<=100;level++){var p=atXp(xp);assertEquals(level,p.level().intValueExact());assertEquals(5*(level-1),p.statPoints().intValueExact());assertEquals(level-1,p.points().intValueExact());xp+=50+20*level;}}
 @Test public void oneConfiguredPracticeAwardCanCrossTwoCharacterLevels(){var props=new Properties();props.setProperty("xp","69");props.setProperty("practice.SWORD","20");var p=PlayerProgress.fromProperties(props);p.awardPractice(Skill.SWORD,5,1);assertEquals(169,p.totalXp().intValueExact());assertEquals(3,p.level().intValueExact());assertEquals(6,p.statPoints().intValueExact());assertEquals(2,p.points().intValueExact());p.awardPractice(Skill.SWORD,0);assertEquals(6,p.statPoints().intValueExact());}
 @Test public void statsCanUseAllFivePointsWithoutConsumingPerks(){var p=atXp(70);for(var stat:PlayerProgress.Stat.values())assertTrue(p.spendStat(stat));assertTrue(p.spendStat(PlayerProgress.Stat.STRENGTH));assertEquals(2,p.stat(PlayerProgress.Stat.STRENGTH));assertEquals(0,p.statPoints().intValueExact());assertEquals(1,p.points().intValueExact());assertFalse(p.spendStat(PlayerProgress.Stat.SPIRIT));assertTrue(p.unlock("spark"));assertEquals(0,p.points().intValueExact());}
 @Test public void statPointsCannotUnlockSkillsAndPerksCannotBuyStats(){var p=atXp(70);assertTrue(p.unlock("spark"));assertEquals(5,p.statPoints().intValueExact());assertFalse(p.unlock("light"));assertTrue(p.spendStat(PlayerProgress.Stat.SPIRIT));assertEquals(4,p.statPoints().intValueExact());assertEquals(0,p.points().intValueExact());assertEquals(Set.of("spark"),p.learned());}
 @Test public void oldAllocatedStatsReceiveOnlyTheBudgetDifference(){var props=new Properties();props.setProperty("schema","1");props.setProperty("xp","1355");props.setProperty("class","MAGE");props.setProperty("style","HEAVY");props.setProperty("practice.FIRE","10000");props.setProperty("learned","spark,mana_control");int[] stats={3,2,1,2};for(var s:PlayerProgress.Stat.values())props.setProperty("stat."+s,Integer.toString(stats[s.ordinal()]));for(int i=0;i<10;i++){var p=PlayerProgress.fromProperties(props);assertEquals(10,p.level().intValueExact());assertEquals(37,p.statPoints().intValueExact());assertEquals(7,p.points().intValueExact());assertEquals(PlayerProgress.PlayerClass.MAGE,p.playerClass());assertEquals(PlayerProgress.SwordStyle.HEAVY,p.style());for(var s:PlayerProgress.Stat.values())assertEquals(stats[s.ordinal()],p.stat(s));props=p.toProperties();}}
 @Test public void concentratingMoreThanNinetyNinePointsSurvivesSnapshots(){var p=atXp(200000);for(int i=0;i<495;i++)assertTrue(p.spendStat(PlayerProgress.Stat.SPIRIT));assertFalse(p.spendStat(PlayerProgress.Stat.SPIRIT));var q=PlayerProgress.fromProperties(p.toProperties());assertEquals(495,q.stat(PlayerProgress.Stat.SPIRIT));assertEquals(0,q.statPoints().intValueExact());assertEquals(99,q.points().intValueExact());assertEquals(p.maxMana(),q.maxMana(),0);}
 @Test public void saveAndReloadNeverRegrantsSpentPoints() throws Exception {
  Path dir=temp.newFolder().toPath();UUID id=UUID.randomUUID();var old=new Properties();old.setProperty("schema","1");old.setProperty("xp","70");old.setProperty("stat.STRENGTH","1");Path file=dir.resolve(id+".properties");try(var out=Files.newBufferedWriter(file)){old.store(out,null);}String original=Files.readString(file);
  var store=new PlayerStore(dir);assertEquals(1,store.get(id).stat(PlayerProgress.Stat.STRENGTH));assertEquals(4,store.get(id).statPoints().intValueExact());assertEquals(original,Files.readString(file));assertTrue(store.get(id).spendStat(PlayerProgress.Stat.SPIRIT));store.forget(id);
  for(int i=0;i<5;i++){store=new PlayerStore(dir);assertEquals(3,store.get(id).statPoints().intValueExact());assertEquals(1,store.get(id).stat(PlayerProgress.Stat.STRENGTH));assertEquals(1,store.get(id).stat(PlayerProgress.Stat.SPIRIT));assertEquals(1,store.get(id).points().intValueExact());store.saveAll();}assertFalse(Files.exists(dir.resolve(id+".tmp")));
 }
 @Test public void legacyLevelHundredKeepsItsRewardsUntilTheNextRealLevel(){var props=new Properties();props.setProperty("xp","199999");props.setProperty("practice.SWORD","20");var p=PlayerProgress.fromProperties(props);p.awardPractice(Skill.SWORD,5,1);assertEquals(200149,p.totalXp().intValueExact());assertEquals(100,p.level().intValueExact());assertEquals(150,p.xpInLevel().intValueExact());assertEquals(495,p.statPoints().intValueExact());}
 @Test public void invalidSavedStatsCannotOverdrawTheBudget(){var props=new Properties();props.setProperty("xp","70");props.setProperty("stat.STRENGTH","9999");props.setProperty("stat.AGILITY","9999");props.setProperty("stat.ENDURANCE","-1");props.setProperty("stat.SPIRIT","NaN");props.setProperty("statPoints","2147483647");var p=PlayerProgress.fromProperties(props);assertEquals(5,p.stat(PlayerProgress.Stat.STRENGTH));assertEquals(0,p.statPoints().intValueExact());assertEquals(0,p.stat(PlayerProgress.Stat.AGILITY));assertFalse(p.spendStat(null));assertFalse(p.spendStat(PlayerProgress.Stat.SPIRIT));}
 @Test public void spendingAndPersistingForOnePlayerDoesNotAffectAnother() throws Exception {var store=new PlayerStore(temp.newFolder().toPath());UUID a=UUID.randomUUID(),b=UUID.randomUUID();store.get(a).awardXp(java.math.BigInteger.valueOf(100));store.get(b).awardXp(java.math.BigInteger.valueOf(100));for(int i=0;i<2;i++){store.get(a).awardPractice(Skill.SWORD,20);store.get(b).awardPractice(Skill.SWORD,20);}assertEquals(3,store.get(a).statPoints().intValueExact());assertEquals(3,store.get(b).statPoints().intValueExact());assertTrue(store.get(a).spendStat(PlayerProgress.Stat.AGILITY));store.saveAll();assertEquals(2,store.get(a).statPoints().intValueExact());assertEquals(3,store.get(b).statPoints().intValueExact());assertEquals(0,store.get(b).stat(PlayerProgress.Stat.AGILITY));}
}
